#!/usr/bin/env bash
# ============================================================================
# VideoMind - Parallel upload (Option A)
# ============================================================================
# Removes the sequential "upload to backend, THEN upload to Shelby" penalty.
# New flow: reserve id (instant) -> backend file upload AND Shelby wallet
# upload run in PARALLEL -> confirm (after BOTH finish).
#
# The backend still receives the full file (Whisper/AI pipeline unchanged).
# All Shelby specifics unchanged: account.address as any, locationHint,
# expirationMicros, blob naming. confirm waits on Promise.all so the temp
# file is always present when the pipeline starts.
#
#   Backend : src/routes/videos.ts        (adds /reserve, prepare reservation-aware)
#   Frontend: src/lib/api.ts              (adds reserveVideo)
#             src/components/upload/UploadZone.tsx (parallel go())
#
#   ./vm_upload_parallel.sh          apply
#   ./vm_upload_parallel.sh --revert restore all three from backups
#
# Run from the repo root (dir containing backend/ and frontend/).
# ============================================================================
set -euo pipefail

VIDEOS="backend/src/routes/videos.ts"
API="frontend/src/lib/api.ts"
UZ="frontend/src/components/upload/UploadZone.tsx"
STAMP="$(date +%Y%m%d-%H%M%S)"
BAKDIR=".vm_uploadparallel_backups"

say() { printf '  %s\n' "$1"; }
die() { printf 'ERROR: %s\n' "$1" >&2; exit 1; }

[ -f "$VIDEOS" ] || die "$VIDEOS not found. Run from repo root (dir with backend/ and frontend/)."
[ -f "$API" ] || die "$API not found."
[ -f "$UZ" ] || die "$UZ not found."

if [ "${1:-}" = "--revert" ]; then
  [ -d "$BAKDIR" ] || die "No backup dir. Nothing to revert."
  LATEST="$(ls -1d $BAKDIR/*/ 2>/dev/null | sort | tail -1)"
  [ -n "$LATEST" ] || die "No backups found."
  cp "$LATEST/videos.ts"     "$VIDEOS"
  cp "$LATEST/api.ts"        "$API"
  cp "$LATEST/UploadZone.tsx" "$UZ"
  say "Reverted 3 files from $LATEST"
  exit 0
fi

if grep -q '/reserve' "$VIDEOS" 2>/dev/null && grep -q 'Promise.all' "$UZ" 2>/dev/null; then
  say "Already applied (reserve + Promise.all present). Use --revert to undo."
  exit 0
fi

mkdir -p "$BAKDIR/$STAMP"
cp "$VIDEOS" "$BAKDIR/$STAMP/videos.ts"
cp "$API"    "$BAKDIR/$STAMP/api.ts"
cp "$UZ"     "$BAKDIR/$STAMP/UploadZone.tsx"
say "Backups saved to $BAKDIR/$STAMP/"

decode() {
  local tmp; tmp="$(mktemp)"
  printf '%s' "$1" | base64 -d > "$tmp" || die "$3: base64 decode failed."
  grep -q "$2" "$tmp" || die "$3: payload verify failed (missing '$2'). Nothing written."
  printf '%s' "$tmp"
}
T_VIDEOS="$(decode "" '/reserve' "videos.ts")"
T_API="$(decode "" 'reserveVideo' "api.ts")"
T_UZ="$(decode "" 'Promise.all' "UploadZone.tsx")"

# critical Shelby markers must survive in the UploadZone payload
grep -q 'locationHint: SHELBY_LOCATION' "$T_UZ" || die "UploadZone payload lost locationHint - aborting."
grep -q 'account.address as any' "$T_UZ" || die "UploadZone payload lost signer shape - aborting."
grep -q 'expirationMicros()' "$T_UZ" || die "UploadZone payload lost expirationMicros - aborting."

cp "$T_VIDEOS" "$VIDEOS"; cp "$T_API" "$API"; cp "$T_UZ" "$UZ"
rm -f "$T_VIDEOS" "$T_API" "$T_UZ"

grep -q '/reserve' "$VIDEOS" || die "videos.ts write verify failed - restore from $BAKDIR/$STAMP"
grep -q 'Promise.all' "$UZ"  || die "UploadZone write verify failed."

say "Applied parallel upload."
say "Verify BOTH packages before deploying:"
say "  cd backend  && npx tsc --noEmit"
say "  cd frontend && npm run build"
